// Moving Average tests. DO NOT edit this file.
// Run with: ./run-tests.sh js
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { MovingAverage } = require('./solution.js');

const EPS = 1e-5;

function check(k, inputs, expected) {
  const m = new MovingAverage(k);
  inputs.forEach((val, i) => {
    const got = m.next(val);
    assert.ok(
      typeof got === 'number' && Math.abs(got - expected[i]) < EPS,
      `k=${k}, call #${i + 1} next(${val}): expected ${expected[i]}, got ${got}`
    );
  });
}

test('1. example from the problem statement', () => {
  check(3, [1, 10, 3, 5], [1, 5.5, 14 / 3, 6]);
});

test('2. window of size 1', () => {
  check(1, [4, -2, 7], [4, -2, 7]);
});

test('3. fewer values than the window size', () => {
  check(5, [2, 4], [2, 3]);
});

test('4. negative values', () => {
  check(2, [-3, -5, 10], [-3, -4, 2.5]);
});

test('5. window sliding several times', () => {
  check(2, [1, 2, 3, 4, 5], [1, 1.5, 2.5, 3.5, 4.5]);
});

test('6. zeros', () => {
  check(3, [0, 0, 0, 0], [0, 0, 0, 0]);
});

test('7. boundary values', () => {
  check(3, [100000, 100000, 100000, -100000], [100000, 100000, 100000, 100000 / 3]);
});

test('8. independent instances', () => {
  const a = new MovingAverage(2);
  const b = new MovingAverage(3);
  const steps = [
    [a, 1, 1], [b, 10, 10], [a, 3, 2], [b, 20, 15],
    [a, 5, 4], [b, 30, 20], [b, 40, 30],
  ];
  steps.forEach(([m, val, exp], i) => {
    const got = m.next(val);
    assert.ok(Math.abs(got - exp) < EPS, `step #${i + 1}: expected ${exp}, got ${got}`);
  });
});

test('9. max constraints: k = 10^4, 10^4 calls with val = 10^5', () => {
  const k = 10000;
  const m = new MovingAverage(k);
  let got = 0;
  for (let i = 0; i < k; i++) got = m.next(100000);
  assert.ok(Math.abs(got - 100000) < EPS, `after ${k} calls: expected 100000, got ${got}`);
});

test('10. stress (beyond constraints, checks O(1)): k = 50,000, 100,000 calls in under 1s', () => {
  const size = 50000;
  const n = 100000;
  const vals = Array.from({ length: n }, (_, i) => ((i * 7919) % 200001) - 100000);

  // reference answer using prefix sums
  const prefix = [0];
  for (const v of vals) prefix.push(prefix[prefix.length - 1] + v);

  const m = new MovingAverage(size);
  const start = performance.now();
  const results = new Array(n);
  for (let i = 0; i < n; i++) results[i] = m.next(vals[i]);
  const elapsed = performance.now() - start;

  for (const i of [0, size - 1, size, n - 1]) {
    const lo = Math.max(0, i + 1 - size);
    const exp = (prefix[i + 1] - prefix[lo]) / (i + 1 - lo);
    assert.ok(Math.abs(results[i] - exp) < EPS, `call #${i + 1}: expected ${exp}, got ${results[i]}`);
  }
  assert.ok(elapsed < 1000, `too slow: ${elapsed.toFixed(0)} ms (limit 1000 ms)`);
});
